package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
public class CacheKeysTest {
 JSONObject library()throws Exception{return new JSONObject().put("id","fixture-library").put("name","Original").put("movie",true).put("paths",new JSONArray().put("/Movies"));}
 @Test public void renameAndUnchangedSettingsKeepSameFileName()throws Exception{JSONObject before=library(),after=new JSONObject(before.toString());assertEquals(CacheKeys.fileName("fixture-owner",before),CacheKeys.fileName("fixture-owner",after));after.put("name","Renamed");assertEquals(CacheKeys.fileName("fixture-owner",before),CacheKeys.fileName("fixture-owner",after));}
 @Test public void sourceAndMediaTypeChangesUseDifferentFileNames()throws Exception{JSONObject before=library(),paths=new JSONObject(before.toString()).put("paths",new JSONArray().put("/Other")),type=new JSONObject(before.toString()).put("movie",false);assertNotEquals(CacheKeys.fileName("fixture-owner",before),CacheKeys.fileName("fixture-owner",paths));assertNotEquals(CacheKeys.fileName("fixture-owner",before),CacheKeys.fileName("fixture-owner",type));}
 @Test public void accountAndLibraryIdentityRemainPartOfKey()throws Exception{JSONObject before=library(),after=new JSONObject(before.toString()).put("id","other-library");assertNotEquals(CacheKeys.fileName("first-owner",before),CacheKeys.fileName("second-owner",before));assertNotEquals(CacheKeys.fileName("first-owner",before),CacheKeys.fileName("first-owner",after));}
 @Test public void twoFixedInputsExactlyMatchPreviousFileNameFormula()throws Exception{JSONObject first=library().put("paths",new JSONArray().put("/Movies").put("/Extras")),second=new JSONObject().put("id","fixture-series").put("movie",false).put("path","/Series/");assertEquals(previous("fixed-owner-one",first),CacheKeys.fileName("fixed-owner-one",first));assertEquals(previous("fixed-owner-two",second),CacheKeys.fileName("fixed-owner-two",second));assertTrue(CacheKeys.fileName("fixed-owner-one",first).matches("[0-9a-f]{64}\\.json"));}
 @Test public void renameAndNoOpNeverRequestDeletion()throws Exception{JSONObject before=library();assertFalse(CacheKeys.changed("owner",before,new JSONObject(before.toString())));assertFalse(CacheKeys.changed("owner",before,new JSONObject(before.toString()).put("name","Renamed")));}
 @Test public void newLibrarySourceOrTypeChangeRequestsInvalidation()throws Exception{JSONObject before=library();assertTrue(CacheKeys.changed("owner",null,before));assertTrue(CacheKeys.changed("owner",before,new JSONObject(before.toString()).put("paths",new JSONArray().put("/Other"))));assertTrue(CacheKeys.changed("owner",before,new JSONObject(before.toString()).put("movie",false)));}
 private String previous(String owner,JSONObject library)throws Exception{String key=owner+":recognition-v3:"+library.getString("id")+":"+library.optBoolean("movie",true)+":"+new JSONArray(LibraryConfig.paths(library)).toString();byte[] hash=MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte v:hash)b.append(String.format("%02x",v));return b+".json";}
}
